ListBucketResult:
    {{ is_truncated }}
    {{ continuation_token }}
    {{ next_continuation_token }}
    {{ key_count }}
    {{ bucket_name }}
    {{ prefix }}
    {{ max_keys }}
{%- for object in objects -%}

        {%- match object.etag -%}
            {%- when Some with (etag) -%}
         "{{ etag }}"
            {%- when None -%}
         {%- endmatch -%}
        {{ object.key }}
        {%- match object.last_modified -%}
            {%- when Some with (last_modified) -%}
        {{ last_modified }}
            {%- when None -%}
         {%- endmatch -%}
        {{ object.size }}
        STANDARD

{%- endfor -%}
